const workflow={purpose:'Implement and locally verify a requested list-interaction change',method:['Turn the requested interactions into failing browser regression cases','Change list state and rendering while preserving selection and navigation','Run the interaction regressions and responsive-layout checks','Review the change and report the verified local preview'],appliesWhen:'A list interaction needs changing in this repository. Each run supplies desired behavior and acceptance criteria; the endpoint is a verified local preview, not a PR, merge or release.'};
function example(feature){
 const records=[{ref:'U',role:'user',text:`Implement ${feature} and verify locally; do not submit or release.`},{ref:'I',role:'toolResult',text:`Browser regressions for ${feature} fail before implementation.`},{ref:'O',role:'toolResult',text:`The implemented ${feature} passes interaction and responsive-layout checks; selection and navigation still work. Local preview reviewed.`}];
 const stages=workflow.method.map((action,i)=>({key:'stage-'+i,action,normalizedAction:action,role:'main',condition:null,refs:[i?'O':'I'],claims:[{description:records[i?2:1].text,basis:'observed',refs:[i?'O':'I']}],tools:[],skills:[]}));
 return {kind:'synthetic',records,fragment:{key:'change',goal:`Implement ${feature}`,context:'Repository list behavior, ending at a verified local preview',state:'completed',refs:['U','I','O'],coverage:{triggerRefs:['U'],outcomeRefs:['O'],gaps:[]},stages,dependencies:[],decisions:[{description:'Local preview only; no submission or release',basis:'requested',refs:['U']}],exceptions:[],questions:[],matching:{goal:`Implement ${feature}`,context:'Preserve selection and navigation and verify interactions at desktop and mobile widths'}}};
}
function examples(){
 const filter=example('workflow-list filtering'),sort=example('session-list sorting');
 const submitted=structuredClone(sort);submitted.fragment.goal+=' and submit a PR';submitted.fragment.matching.goal=submitted.fragment.goal;submitted.records[0].text='Implement session-list sorting and submit a PR; do not merge or release.';submitted.records[2].text+=' A PR was created.';submitted.fragment.decisions[0].description='Submit a PR; do not merge or release';submitted.fragment.stages[3].action=submitted.fragment.stages[3].normalizedAction='Push the verified change and create a pull request';submitted.fragment.stages[3].claims[0].description='A PR was created';
 const discussion=structuredClone(filter);discussion.fragment.goal=discussion.fragment.matching.goal='Explain a proposed workflow-list filter';discussion.records[0].text='Explain filtering without implementing it';discussion.records[1].text='The existing list behavior was inspected';discussion.records[2].text='A design explanation was provided; no code changed';discussion.fragment.stages=discussion.fragment.stages.slice(0,2);discussion.fragment.stages.forEach((stage,i)=>{stage.action=stage.normalizedAction=i?'Explain a proposed interaction design without implementing it':'Inspect the existing list interaction';stage.claims[0].description=discussion.records[i+1].text;});discussion.fragment.decisions[0].description='Explanation only; no implementation';
 return [{name:'different-features-same-local-implementation-procedure',expected:{sameWorkflow:true,relations:['same_workflow_candidate']},left:filter,right:sort},{name:'same-feature-local-preview-versus-pr',expected:{sameWorkflow:false,relations:['different','shared_subprocedure']},left:sort,right:submitted},{name:'feature-explanation-is-not-implementation',expected:{sameWorkflow:false,relations:['different','common_practice','shared_subprocedure']},left:filter,right:discussion}];
}
const guidance={inputs:[{name:'desired_behavior',label:'Desired behavior',description:'The requested list interactions and behavior to implement',required:true},{name:'acceptance_criteria',label:'Acceptance criteria',description:'Observable outcomes and cases that this run must satisfy',required:true}],steps:workflow.method.map((approach,i)=>({step:i+1,approach:approach+' using desired_behavior and acceptance_criteria',checks:['Check the supplied acceptance_criteria against observed results']})),review:['Review scope, behavior and regression evidence'],completion:['The supplied desired_behavior and acceptance_criteria are verified in the local preview; no submission or release'],risks:['Missing requirements must be clarified rather than copied from a historical feature']};
module.exports={examples,workflow,guidance};
